"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-toggle";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { useFlowPress } from "@/lib/sahajiv-motion/flow-press";
export const toggleVariants = cva(
  "v-toggle [place-items:center] [border-radius:var(--r-pill)] [font-size:var(--fs-control)] [display:inline-flex] [align-items:center] [justify-content:center] [height:40px] [min-width:40px] [padding:0_16px] [gap:8px] [background:var(--v-canvas)] [color:var(--v-text-2)] [font-weight:500] [box-shadow:inset_0_0_0_1px_var(--v-edge)] [cursor:pointer]",
  {
    variants: {
      variant: {
        default: "",
        pressed: "-pressed",
        pink: "-pink",
        circle: "-circle w-10 px-0 rounded-full text-[12.5px] font-semibold",
      },
    },
    defaultVariants: { variant: "default" },
  },
);
export type ToggleProps = React.ComponentProps<typeof Primitive.Root> &
  VariantProps<typeof toggleVariants>;
export function Toggle({ ref, className, variant, ...props }: ToggleProps) {
  const morphRef = useMorph<HTMLButtonElement>("buttons", ref);
  const flowRef = useFlowPress(morphRef);
  return (
    <Primitive.Root
      ref={flowRef}
      data-slot="toggle"
      data-part="root"
      data-toggle=""
      className={cn(toggleVariants({ variant }), className)}
      {...props}
    />
  );
}
export type ToggleWellProps = React.ComponentProps<"div">;
export function ToggleWell({ className, ...props }: ToggleWellProps) {
  return (
    <div
      data-slot="toggle-well"
      className={cn("v-togglewell", className)}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"])[data-morph] {
  --mfill: var(--v-ink);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[data-morph] {
  --mfill: var(--v-pink);
}
@media (max-width: 640px) {
  .v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]).-circle {
    width: 32px;
    min-width: 32px;
    height: 32px;
    font-size: 11px;
  }
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[aria-pressed="true"] {
  color: var(--v-on-accent);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"] {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[aria-pressed="true"] {
  background: var(--v-pink);
  color: var(--v-text);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]).-circle {
  width: var(--ctl-md);
  padding: 0;
  border-radius: 50%;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):not(
    [aria-pressed="true"]
  ) {
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):not(:disabled) {
  cursor: pointer;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):disabled {
  cursor: not-allowed;
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[aria-pressed="true"] {
  background: var(--sel-bg);
  color: var(--sel-ink);
  box-shadow: inset 0 0 0 1px var(--sel-edge);
}
:root[data-mode="dark"]
  .v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"] {
  background: var(--v-pink);
  color: var(--v-on-accent);
  border-color: var(--v-pink);
}
:root[data-mode="dark"]
  .v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):not(
    [aria-pressed="true"]
  ) {
  color: var(--v-text);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):disabled {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  opacity: 1;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]) {
  transition:
    background var(--t-micro),
    color var(--t-micro),
    box-shadow var(--t-micro),
    border-radius var(--t-max) var(--enter),
    transform var(--t-micro) var(--enter);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):hover {
  background: var(--v-beige);
  color: var(--v-text);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):active {
  transform: scale(0.96);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"] {
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: none;
  border-radius: 999px 999px 999px 8px;
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[aria-pressed="true"] {
  background: var(--v-pink);
  color: var(--v-on-accent);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-yellow[aria-pressed="true"] {
  background: var(--v-yellow);
  color: var(--v-on-accent);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-olive[aria-pressed="true"] {
  background: var(--v-olive);
  color: var(--v-on-accent);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-blue[aria-pressed="true"] {
  background: var(--v-blue);
  color: var(--v-on-accent);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]).-circle {
  width: 40px;
  padding: 0;
  border-radius: 50%;
  font-size: 12.5px;
  font-weight: 600;
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-circle[aria-pressed="true"] {
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]) .v-icon {
  width: 16px;
  height: 16px;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"])[data-morph] {
  --mfill: var(--v-canvas);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"][data-morph] {
  --mfill: var(--v-ink);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-pink[aria-pressed="true"][data-morph] {
  --mfill: var(--v-pink);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-yellow[aria-pressed="true"][data-morph] {
  --mfill: var(--v-yellow);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-olive[aria-pressed="true"][data-morph] {
  --mfill: var(--v-olive);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  ).-blue[aria-pressed="true"][data-morph] {
  --mfill: var(--v-blue);
}
.v-togglewell:where([data-slot="toggle"], [data-slot^="toggle-"]) {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  border-radius: 999px;
  background: var(--card);
}
.v-togglewell:where([data-slot="toggle"], [data-slot^="toggle-"]) .v-toggle {
  box-shadow: none;
  background: transparent;
}
.v-togglewell:where([data-slot="toggle"], [data-slot^="toggle-"])
  .v-toggle:hover {
  background: var(--v-canvas);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]) {
  transition:
    background var(--t-micro),
    color var(--t-micro),
    transform var(--t-micro) var(--enter);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):active:not(
    :disabled
  ) {
  transform: scale(0.95);
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):disabled {
  cursor: not-allowed;
}
.v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]) .v-icon {
  transition: transform var(--t-element) var(--enter);
}
.v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"]
  .v-icon {
  transform: scale(1.1) rotate(-8deg);
}
:root[data-mode="dark"]
  .v-toggle:where(
    [data-slot="toggle"],
    [data-slot^="toggle-"]
  )[aria-pressed="true"]:not(.-pink):not(.-yellow):not(.-olive):not(.-blue):not(.-circle) {
  background: var(--v-pink);
  color: var(--v-on-accent);
}
:root[data-mode="dark"]
  .v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]) {
  background: var(--v-beige-2);
  color: var(--v-text-2);
}
:root[data-mode="dark"]
  .v-toggle:where([data-slot="toggle"], [data-slot^="toggle-"]):hover {
  background: var(--v-beige);
  color: var(--v-text);
}
:root[data-mode="dark"]
  .v-togglewell:where([data-slot="toggle"], [data-slot^="toggle-"]) {
  background: var(--v-beige);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="toggle"],
  [data-slot^="toggle-"],
  [data-slot="toggle"]::before,
  [data-slot="toggle"]::after,
  [data-slot^="toggle-"]::before,
  [data-slot^="toggle-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* Authored circle selection precedence (components-2.css:1359). */
.v-toggle:where([data-slot="toggle"],[data-slot^="toggle-"]).-circle[aria-pressed="true"]:not([data-glide-active]) {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
.v-toggle:where([data-slot="toggle"],[data-slot^="toggle-"]).-circle[aria-pressed="true"]:not([data-glide-active])[data-morph] {
  --mfill: var(--v-ink);
}

}
